from django.views import View
from django.http import JsonResponse, HttpResponseForbidden
from django.contrib.auth.mixins import LoginRequiredMixin
from django.core.cache import cache

class CacheTagPurgeView(LoginRequiredMixin, View):
    def post(self, request, tag_slug):
        user_tenant_slug = request.user.organization.slug
        # Enforce that the purged tag belongs to the caller's organization namespace
        if not tag_slug.startswith(f"{user_tenant_slug}_") and not request.user.is_staff:
            return HttpResponseForbidden("Cannot clear cache tags outside your organization namespace")

        cache_key = f"api_view_tag:{tag_slug}"
        cache.delete(cache_key)
        return JsonResponse({"purged_tag": tag_slug, "status": "cleared"})
